 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    # Full-width color bars encode a periodic sequence of row colors.
    row_clues = {r: row[0] for r, row in enumerate(grid)
                 if row[0] != 0 and all(v == row[0] for v in row)}
    if row_clues:
        period = len(row_clues)
        by_residue = {}
        for r, color in row_clues.items():
            residue = r % period
            if residue in by_residue and by_residue[residue] != color:
                raise ValueError("inconsistent row-period clues")
            by_residue[residue] = color
        if len(by_residue) != period:
            raise ValueError("row clues do not determine all residues")
        return [[by_residue[r % period]] * w for r in range(h)]

    # Otherwise, same-color diagonals of constant (row + column) encode
    # the residues of a periodic diagonal coloring.
    diagonal_clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                key = r + c
                if key in diagonal_clues and diagonal_clues[key] != color:
                    raise ValueError("mixed colors on a clue diagonal")
                diagonal_clues[key] = color
    period = len(diagonal_clues)
    by_residue = {}
    for diagonal, color in diagonal_clues.items():
        residue = diagonal % period
        if residue in by_residue and by_residue[residue] != color:
            raise ValueError("inconsistent diagonal-period clues")
        by_residue[residue] = color
    if len(by_residue) != period:
        raise ValueError("diagonal clues do not determine all residues")
    return [[by_residue[(r + c) % period] for c in range(w)] for r in range(h)]


